// Lazy on purpose: the cursor is a desktop-only flourish, and this keeps its
// JS *and* its CSS out of the bundle a phone downloads. The chunk is only
// requested once we know there's a real mouse on a wide enough screen.
// `?cursor=off` falls back to the native cursor.
const AgentCursor3D = lazy(() => import("./AgentCursor3D"));

const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

const isFinePointer = () =>
  typeof window !== "undefined" &&
  window.matchMedia &&
  window.matchMedia("(pointer: fine)").matches;

