// ============================================
// COUNT-UP NUMBER (animates when in view)
// ============================================
function CountUp({ value, suffix = "" }) {
  const ref = useRef(null);
  const [display, setDisplay] = useState(prefersReducedMotion() ? value : 0);

  useEffect(() => {
    if (prefersReducedMotion()) {
      setDisplay(value);
      return;
    }
    const el = ref.current;
    if (!el) return;
    let raf = null;
    const io = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return;
        io.disconnect();
        const start = performance.now();
        const dur = 1200;
        const tick = (now) => {
          const t = Math.min((now - start) / dur, 1);
          const eased = 1 - Math.pow(1 - t, 3);
          setDisplay(Math.round(eased * value));
          if (t < 1) raf = requestAnimationFrame(tick);
        };
        raf = requestAnimationFrame(tick);
      },
      { threshold: 0.5 }
    );
    io.observe(el);
    return () => {
      io.disconnect();
      if (raf) cancelAnimationFrame(raf);
    };
  }, [value]);

  return (
    <span ref={ref}>
      {display}
      {suffix}
    </span>
  );
}

// ============================================
// LIVE TERMINAL — auto-types agent runs
// ============================================
function AgentTerminal() {
  const [lines, setLines] = useState([]);
  const [current, setCurrent] = useState("");
  const stateRef = useRef({ script: 0, line: 0, char: 0 });
  const timerRef = useRef(null);

  useEffect(() => {
    if (prefersReducedMotion()) {
      setLines(TERMINAL_SCRIPTS[0]);
      return;
    }
    const step = () => {
      const s = stateRef.current;
      const script = TERMINAL_SCRIPTS[s.script];
      const line = script[s.line];

      if (!line) {
        // Script finished — hold, then wipe and move to the next one
        timerRef.current = setTimeout(() => {
          stateRef.current = {
            script: (s.script + 1) % TERMINAL_SCRIPTS.length,
            line: 0,
            char: 0,
          };
          setLines([]);
          setCurrent("");
          step();
        }, 2600);
        return;
      }

      if (s.char < line.t.length) {
        const isCmd = line.cls === "cmd";
        s.char += isCmd ? 1 : 3; // commands "type", output "prints"
        setCurrent(line.t.slice(0, s.char));
        timerRef.current = setTimeout(step, isCmd ? 34 : 12);
      } else {
        setLines((prev) => [...prev, line]);
        setCurrent("");
        s.line += 1;
        s.char = 0;
        timerRef.current = setTimeout(step, line.cls === "cmd" ? 420 : 210);
      }
    };
    timerRef.current = setTimeout(step, 900);
    return () => clearTimeout(timerRef.current);
  }, []);

  const currentCls =
    TERMINAL_SCRIPTS[stateRef.current.script]?.[stateRef.current.line]?.cls ||
    "cmd";

  return (
    <div className="ash-terminal" aria-hidden="true">
      <div className="ash-terminal-bar">
        <span className="ash-tdot ash-tdot-r" />
        <span className="ash-tdot ash-tdot-y" />
        <span className="ash-tdot ash-tdot-g" />
        <span className="ash-terminal-title">laxman@ai-experience-center</span>
        <span className="ash-terminal-live">● live</span>
      </div>
      <div className="ash-terminal-body">
        {lines.map((l, i) => (
          <div key={i} className={`ash-tline ash-tline-${l.cls}`}>
            {l.t}
          </div>
        ))}
        <div className={`ash-tline ash-tline-${currentCls}`}>
          {current}
          <span className="ash-tcursor">▋</span>
        </div>
      </div>
    </div>
  );
}

// ============================================
// AGENT ORCHESTRA — interactive SVG network
// ============================================
function AgentOrchestra() {
  const [active, setActive] = useState(0);
  // Hover and keyboard focus both hold the diagram on one agent, so tabbing
  // through the nodes behaves the same as pointing at them.
  const [held, setHeld] = useState(null);
  const idx = held !== null ? held : active;
  const reduced = prefersReducedMotion();

  useEffect(() => {
    if (reduced || held !== null) return;
    const id = setInterval(
      () => setActive((a) => (a + 1) % AGENTS.length),
      2600
    );
    return () => clearInterval(id);
  }, [held, reduced]);

  const W = 760;
  const H = 430;
  const CX = W / 2;
  const CY = H / 2;
  // Radii pushed out from 250×138: the ring only filled the middle two thirds
  // of the viewBox, leaving ~130px of empty gutter down each side.
  const positions = useMemo(
    () =>
      AGENTS.map((_, i) => {
        const angle = (i / AGENTS.length) * Math.PI * 2 - Math.PI / 2;
        return {
          x: CX + Math.cos(angle) * 292,
          y: CY + Math.sin(angle) * 146,
        };
      }),
    [CX, CY]
  );

  return (
    <div
      className="ash-orchestra"
      data-ash-reveal
      style={{ "--ash-active": AGENTS[idx].hue }}
    >
      <svg
        viewBox={`0 0 ${W} ${H}`}
        className="ash-orchestra-svg"
        aria-label="Six AI agents connected to one task"
      >
        <defs>
          {/* One lit-from-upper-left gradient per agent, so a node reads as a
              sphere in its own colour rather than a flat disc. */}
          {AGENTS.map((agent, i) => (
            <radialGradient
              key={agent.name}
              id={`ash-node-${i}`}
              cx="34%"
              cy="26%"
              r="82%"
            >
              <stop offset="0" stopColor={agent.hue} stopOpacity="0.62" />
              <stop offset="1" stopColor={agent.hue} stopOpacity="0.14" />
            </radialGradient>
          ))}
        </defs>

        {/* Edges, plus a packet travelling agent → task. The direction is the
            whole point of the diagram: six specialists feeding one request. */}
        {positions.map((p, i) => (
          <g key={`e-${i}`} style={{ "--ash-hue": AGENTS[i].hue }}>
            <line
              x1={CX}
              y1={CY}
              x2={p.x}
              y2={p.y}
              className={`ash-edge ${i === idx ? "ash-edge-active" : ""}`}
            />
            {!reduced && (
              <circle r="3.2" className="ash-packet">
                <animateMotion
                  dur="3.6s"
                  begin={`${i * 0.6}s`}
                  repeatCount="indefinite"
                  path={`M ${p.x} ${p.y} L ${CX} ${CY}`}
                />
                <animate
                  attributeName="opacity"
                  values="0;1;1;0"
                  keyTimes="0;0.18;0.72;1"
                  dur="3.6s"
                  begin={`${i * 0.6}s`}
                  repeatCount="indefinite"
                />
              </circle>
            )}
          </g>
        ))}

        {/* Center task node */}
        <g className="ash-center-node">
          {!reduced && (
            <circle cx={CX} cy={CY} r="46" className="ash-center-ping" />
          )}
          <circle cx={CX} cy={CY} r="46" className="ash-center-ring" />
          <circle cx={CX} cy={CY} r="38" className="ash-center-core" />
          <text
            x={CX}
            y={CY - 4}
            textAnchor="middle"
            className="ash-center-emoji"
          >
            ⚡
          </text>
          <text
            x={CX}
            y={CY + 16}
            textAnchor="middle"
            className="ash-center-label"
          >
            your task
          </text>
        </g>

        {/* Agent nodes */}
        {AGENTS.map((agent, i) => {
          const p = positions[i];
          const isOn = i === idx;
          return (
            <g
              key={agent.name}
              className={`ash-agent-node ${isOn ? "ash-agent-active" : ""}`}
              style={{ "--ash-hue": agent.hue }}
              role="button"
              tabIndex={0}
              data-cursor={agent.name}
              aria-label={`${agent.name} — ${agent.blurb}`}
              onMouseEnter={() => setHeld(i)}
              onMouseLeave={() => setHeld(null)}
              onFocus={() => setHeld(i)}
              onBlur={() => setHeld(null)}
              onClick={() => setActive(i)}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  setActive(i);
                }
              }}
            >
              {/* Only the disc scales on focus — the label is outside this
                  group so it stays put and legible. */}
              <g className="ash-agent-body">
                <circle cx={p.x} cy={p.y} r="34" className="ash-agent-halo" />
                <circle
                  cx={p.x}
                  cy={p.y}
                  r="24"
                  className="ash-agent-core"
                  fill={`url(#ash-node-${i})`}
                />
                <text
                  x={p.x}
                  y={p.y + 6}
                  textAnchor="middle"
                  className="ash-agent-emoji"
                >
                  {agent.icon}
                </text>
              </g>
              <text
                x={p.x}
                y={p.y + (p.y > CY ? 50 : -40)}
                textAnchor="middle"
                className="ash-agent-label"
              >
                {agent.name}
              </text>
            </g>
          );
        })}
      </svg>

      <div className="ash-orchestra-caption" aria-live="polite">
        <span className="ash-orchestra-icon">{AGENTS[idx].icon}</span>
        <div>
          <strong>{AGENTS[idx].name}</strong>
          <p>{AGENTS[idx].blurb}</p>
        </div>
      </div>
    </div>
  );
}

// ============================================
// TILT CARD — 3D hover tilt (fine pointers)
// ============================================
// matchMedia allocates a MediaQueryList on every call and the tilt handler
// runs on every mousemove across fifteen cards, so the answer is cached.
let tiltAllowed = null;
const canTilt = () => {
  if (tiltAllowed === null) {
    tiltAllowed = isFinePointer() && !prefersReducedMotion();
  }
  return tiltAllowed;
};

// ============================================
// MAGNIFY — a lens that enlarges the heading under the cursor
// ============================================
// A real magnifier rather than a hover-scale: a second copy of the text is
// scaled up and clipped to a circle that tracks the pointer, so the words
// under the glass grow while the rest of the line stays put.
//
// Three details make it work:
//   • The clip lives on an untransformed wrapper and the scale on its child.
//     Both on one element and the circle would be scaled along with the text.
//   • transform-origin is set to the cursor position, which is what pins the
//     point under the glass so it magnifies in place instead of sliding away.
//   • The base copy is masked out inside the circle. Without that hole the
//     original text reads straight through the enlarged one and the heading
//     looks doubled — which is also what a real lens does: it occludes.
//
// Position is published as two CSS variables and the clip, the mask, the
// origin and the ring all derive from them, so a move costs two property
// writes rather than a style write per element.
//
// The copy is mounted only while hovering, so the prerendered HTML a crawler
// sees contains each heading exactly once.
function Magnify({ children, zoom = 1.55, radius = 88 }) {
  const [on, setOn] = useState(false);
  const wrapRef = useRef(null);
  const rafRef = useRef(null);

  const place = useCallback((x, y) => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    rafRef.current = requestAnimationFrame(() => {
      rafRef.current = null;
      const wrap = wrapRef.current;
      if (!wrap) return;
      wrap.style.setProperty("--mag-x", `${x}px`);
      wrap.style.setProperty("--mag-y", `${y}px`);
    });
  }, []);

  const onEnter = useCallback(
    (e) => {
      if (!canTilt()) return;
      const r = e.currentTarget.getBoundingClientRect();
      place(e.clientX - r.left, e.clientY - r.top);
      setOn(true);
    },
    [place]
  );

  const onMove = useCallback(
    (e) => {
      if (!canTilt()) return;
      const r = e.currentTarget.getBoundingClientRect();
      place(e.clientX - r.left, e.clientY - r.top);
    },
    [place]
  );

  const onLeave = useCallback(() => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    rafRef.current = null;
    setOn(false);
  }, []);

  useEffect(
    () => () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    },
    []
  );

  return (
    <span
      className={`ash-mag ${on ? "ash-mag-on" : ""}`}
      ref={wrapRef}
      style={{ "--mag-r": `${radius}px`, "--mag-zoom": zoom }}
      onMouseEnter={onEnter}
      onMouseMove={onMove}
      onMouseLeave={onLeave}
    >
      <span className="ash-mag-base">{children}</span>
      {on && (
        <>
          <span className="ash-mag-lens" aria-hidden="true">
            <span className="ash-mag-inner">{children}</span>
          </span>
          <span className="ash-mag-ring" aria-hidden="true" />
        </>
      )}
    </span>
  );
}

function TiltCard({ children, className, style, ...rest }) {
  const ref = useRef(null);
  const rafRef = useRef(null);

  const onMove = useCallback((e) => {
    if (!canTilt()) return;
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    rafRef.current = requestAnimationFrame(() => {
      const el = ref.current;
      if (!el) return;
      const r = el.getBoundingClientRect();
      const x = e.clientX - r.left;
      const y = e.clientY - r.top;
      const rx = ((r.height / 2 - y) / r.height) * 8;
      const ry = ((x - r.width / 2) / r.width) * 8;
      el.style.transform = `perspective(800px) rotateX(${rx}deg) rotateY(${ry}deg) translateY(-6px)`;
      el.style.setProperty("--mx", `${x}px`);
      el.style.setProperty("--my", `${y}px`);
    });
  }, []);

  const onLeave = useCallback(() => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    if (ref.current) ref.current.style.transform = "";
  }, []);

  return (
    <article
      ref={ref}
      className={className}
      style={style}
      onMouseMove={onMove}
      onMouseLeave={onLeave}
      {...rest}
    >
      {children}
    </article>
  );
}

// ============================================
// MAIN
// ============================================
const AgentsShowcase = ({ theme, setTheme, isPreview = false }) => {
  const [nudgeTool, setNudgeTool] = useState(null);
  // Starts false and is decided in an effect, so the prerendered markup and
  // the first client render always agree.
  const [customCursor, setCustomCursor] = useState(false);
  const signinRef = useRef(null);
  const nudgeTimer = useRef(null);
  const rootRef = useRef(null);
  const heroRef = useRef(null);
  const heroInnerRef = useRef(null);
  const heroBgRef = useRef(null);
  const spotRef = useRef(null);
  const progressRef = useRef(null);

  const handleTry = useCallback((tool) => {
    setNudgeTool(tool.name);
    signinRef.current?.scrollIntoView({ behavior: "smooth", block: "center" });
    clearTimeout(nudgeTimer.current);
    nudgeTimer.current = setTimeout(() => setNudgeTool(null), 6000);
  }, []);

  useEffect(() => () => clearTimeout(nudgeTimer.current), []);

  // ---- Desktop-only custom cursor ----
  // Live-tracked rather than checked once: plugging a mouse into a tablet, or
  // dragging a desktop window down to phone width, both flip this correctly.
  useEffect(() => {
    if (typeof window.matchMedia !== "function") return undefined;
    const mq = window.matchMedia(CUSTOM_CURSOR_QUERY);
    const sync = () => setCustomCursor(mq.matches);
    sync();
    if (mq.addEventListener) {
      mq.addEventListener("change", sync);
      return () => mq.removeEventListener("change", sync);
    }
    mq.addListener(sync); // Safari < 14
    return () => mq.removeListener(sync);
  }, []);

  // ?cursor=off is an escape hatch back to the native cursor.
  const cursorOff = useMemo(
    () =>
      typeof window !== "undefined" &&
      new URLSearchParams(window.location.search).get("cursor") === "off",
    []
  );

  // ---- One rAF-throttled scroll listener: progress bar, hero parallax,
  // ---- orb drift, and per-element parallax via [data-ash-speed] ----
  useEffect(() => {
    if (prefersReducedMotion()) return;
    let raf = null;
    const parallaxEls = rootRef.current
      ? Array.from(rootRef.current.querySelectorAll("[data-ash-speed]")).map(
          (el) => ({ el, speed: parseFloat(el.dataset.ashSpeed) || 0, base: 0 })
        )
      : [];

    // Measure once (and on resize) with the transforms cleared. Reading
    // getBoundingClientRect inside the scroll loop meant a forced layout per
    // element per frame, *and* each read was polluted by the transform the
    // previous frame had just written.
    let docMax = 1;
    const measure = () => {
      parallaxEls.forEach((p) => {
        p.el.style.transform = "";
      });
      const vh = window.innerHeight;
      parallaxEls.forEach((p) => {
        const rect = p.el.getBoundingClientRect();
        p.base = rect.top + window.scrollY + rect.height / 2 - vh / 2;
      });
      docMax = document.documentElement.scrollHeight - vh || 1;
    };

    // Only write a style when the value it encodes actually changed — opacity
    // on the hero backdrop repaints a full-screen layer with a WebGL canvas in
    // it, which is not something to do 60 times a second for no visual change.
    let lastFade = -1;
    const update = () => {
      raf = null;
      const y = window.scrollY;
      if (progressRef.current) {
        progressRef.current.style.transform = `scaleX(${Math.min(
          y / docMax,
          1
        )})`;
      }
      const fade = Math.round(Math.min(y / 560, 1) * 100) / 100;
      if (fade !== lastFade) {
        lastFade = fade;
        if (heroInnerRef.current) {
          heroInnerRef.current.style.transform = `translate3d(0, ${y * 0.22}px, 0)`;
          heroInnerRef.current.style.opacity = `${1 - fade * 0.8}`;
        }
        // The backdrop has to leave with the copy. Fading only the text left
        // the starfield and the 3D ring at full strength over dimmed content,
        // which read as a rendering fault rather than a parallax.
        if (heroBgRef.current) {
          heroBgRef.current.style.opacity = `${1 - fade * 0.85}`;
        }
      } else if (fade < 1 && heroInnerRef.current) {
        heroInnerRef.current.style.transform = `translate3d(0, ${y * 0.22}px, 0)`;
      }
      parallaxEls.forEach((p) => {
        p.el.style.transform = `translate3d(0, ${
          (p.base - y) * p.speed * -0.1
        }px, 0)`;
      });
    };
    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(update);
    };
    const onResize = () => {
      measure();
      onScroll();
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onResize);
    // Fonts and the hero canvas can settle after mount and shift the bases.
    window.addEventListener("load", onResize);
    measure();
    update();
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onResize);
      window.removeEventListener("load", onResize);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  // ---- Cursor spotlight in the hero (fine pointers only) ----
  useEffect(() => {
    if (prefersReducedMotion() || !isFinePointer()) return;
    const hero = heroRef.current;
    const spot = spotRef.current;
    if (!hero || !spot) return;
    let raf = null;
    const onMove = (e) => {
      const rect = hero.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      if (!raf) {
        raf = requestAnimationFrame(() => {
          raf = null;
          spot.style.transform = `translate(${x}px, ${y}px) translate(-50%, -50%)`;
          spot.style.opacity = "1";
        });
      }
    };
    const onLeave = () => {
      spot.style.opacity = "0";
    };
    hero.addEventListener("mousemove", onMove);
    hero.addEventListener("mouseleave", onLeave);
    return () => {
      hero.removeEventListener("mousemove", onMove);
      hero.removeEventListener("mouseleave", onLeave);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  // ---- Reveal-on-scroll ----
  useEffect(() => {
    const els = rootRef.current
      ? rootRef.current.querySelectorAll("[data-ash-reveal]")
      : [];
    if (prefersReducedMotion()) {
      els.forEach((el) => el.classList.add("ash-revealed"));
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            e.target.classList.add("ash-revealed");
            io.unobserve(e.target);
          }
        });
      },
      { threshold: 0.08, rootMargin: "0px 0px -30px 0px" }
    );
    els.forEach((el) => io.observe(el));
    return () => io.disconnect();
  }, []);

  const signinBlock = !isPreview ? (
    <div className="ash-signin-btn" data-cursor="Sign in">
      <LoginButton theme={theme} />
    </div>
  ) : (
    <a className="ash-enter-btn" href="/myspace" data-cursor="Enter">
      Enter your workspace →
    </a>
  );

  return (
    <div
      className="ash-page"
      data-theme={theme?.name}
      ref={rootRef}
      style={{
        "--ash-body": theme.body,
        "--ash-text": theme.text,
        "--ash-sub": theme.secondaryText,
        "--ash-accent": theme.accentColor,
      }}
    >
      {/* Custom cursor — desktop only; the chunk isn't fetched otherwise */}
      {customCursor && !cursorOff && (
        <Suspense fallback={null}>
          <AgentCursor3D />
        </Suspense>
      )}

      {/* Scroll progress */}
      <div className="ash-progress" aria-hidden="true">
        <div className="ash-progress-fill" ref={progressRef} />
      </div>

      <Header theme={theme} setTheme={setTheme} />

      {isPreview && (
        <div className="ash-preview-banner">
          <span>👁️ You're viewing the public page visitors see.</span>
          <a href="/myspace">Back to your workspace →</a>
        </div>
      )}

      {/* ================= HERO ================= */}
      <section className="ash-hero" ref={heroRef}>
        <div className="ash-hero-bg" ref={heroBgRef} aria-hidden="true">
          <AshHero3D />
          <div className="ash-orb ash-orb-1" data-ash-speed="1.6" />
          <div className="ash-orb ash-orb-2" data-ash-speed="2.4" />
          <div className="ash-grid" />
          <div className="ash-spot" ref={spotRef} />
          {/* Floating tool glyphs drifting at different depths */}
          <span className="ash-float ash-float-1" data-ash-speed="3">
            🧠
          </span>
          <span className="ash-float ash-float-2" data-ash-speed="4.5">
            🤖
          </span>
          <span className="ash-float ash-float-3" data-ash-speed="2.2">
            🎯
          </span>
          <span className="ash-float ash-float-4" data-ash-speed="3.8">
            🚀
          </span>
        </div>

        <div className="ash-hero-inner" ref={heroInnerRef}>
          <p className="ash-eyebrow">
            <span className="ash-live-dot" aria-hidden="true" />
            Live AI workspace — not mockups
          </p>
          <h1 className="ash-title">
            <Magnify radius={104} zoom={1.45}>
              {"The AI Experience".split(" ").map((w, i) => (
                <span
                  className="ash-title-word"
                  style={{ animationDelay: `${0.08 + i * 0.1}s` }}
                  key={i}
                >
                  {w}&nbsp;
                </span>
              ))}
              <span
                className="ash-title-word ash-title-grad"
                style={{ animationDelay: "0.38s" }}
              >
                Center
              </span>
            </Magnify>
          </h1>
          <p className="ash-sub">
            Nine working AI tools Laxman designed, built and shipped inside this
            portfolio — a RAG brain, collaborating agents, a resume tailor, a
            job-hunt copilot and more. Everything below is real and running.
          </p>

          {/* Live terminal demo */}
          <AgentTerminal />

          <div className="ash-stats" data-ash-reveal>
            <div className="ash-stat">
              <span className="ash-stat-num">
                <CountUp value={9} />
              </span>
              <span className="ash-stat-label">AI tools</span>
            </div>
            <div className="ash-stat">
              <span className="ash-stat-num">
                <CountUp value={6} />
              </span>
              <span className="ash-stat-label">collaborating agents</span>
            </div>
            <div className="ash-stat">
              <span className="ash-stat-num">
                <CountUp value={60} suffix="+" />
              </span>
              <span className="ash-stat-label">RAG knowledge nodes</span>
            </div>
            <div className="ash-stat">
              <span className="ash-stat-num">
                <CountUp value={3} />
              </span>
              <span className="ash-stat-label">LLM fallback chain</span>
            </div>
          </div>

          {/* Sign-in card */}
          <div
            ref={signinRef}
            className={`ash-signin ${nudgeTool ? "ash-signin-nudge" : ""}`}
          >
            {nudgeTool ? (
              <p className="ash-signin-title ash-signin-nudge-text">
                🔓 Sign in to launch <strong>{nudgeTool}</strong> — free with
                any Google account
              </p>
            ) : (
              <p className="ash-signin-title">
                Try everything free — sign in with Google
              </p>
            )}
            {signinBlock}
            <p className="ash-signin-note">
              Sign-in keeps LLM usage fair and saves your sessions privately. No
              emails, no spam.
            </p>
          </div>

          <button
            type="button"
            className="ash-scroll-cue"
            data-cursor="Explore"
            onClick={() =>
              document
                .getElementById("ash-orchestra")
                ?.scrollIntoView({ behavior: "smooth" })
            }
          >
            Explore ↓
          </button>
        </div>
      </section>

      {/* ================= MARQUEE ================= */}
      <div className="ash-marquee" aria-hidden="true">
        <div className="ash-marquee-track">
          {[0, 1].map((copy) => (
            <div className="ash-marquee-group" key={copy}>
              {MARQUEE.map((m) => (
                <span className="ash-marquee-item" key={`${copy}-${m}`}>
                  {m}
                  <span className="ash-marquee-dot">✦</span>
                </span>
              ))}
            </div>
          ))}
        </div>
      </div>

      {/* ================= AGENT ORCHESTRA ================= */}
      <section className="ash-orchestra-section" id="ash-orchestra">
        <div className="ash-section-head" data-ash-reveal>
          <span className="ash-kicker">01 — The team</span>
          <h2>Six agents, one task</h2>
          <p>
            Give the workspace a task and specialized agents pick it up in
            relay. Hover or tap an agent to see its role.
          </p>
        </div>
        <div data-ash-reveal>
          <AgentOrchestra />
        </div>
      </section>

      {/* ================= GALLERY ================= */}
      <section className="ash-gallery" id="ash-gallery">
        <div className="ash-section-head" data-ash-reveal>
          <span className="ash-kicker">02 — What's inside</span>
          <h2>
            <Magnify>Nine tools, all working</Magnify>
          </h2>
          <p>
            Each card below is a live feature behind the sign-in — this is the
            actual feature list, not a roadmap.
          </p>
        </div>

        <div className="ash-cards">
          {TOOLS.map((tool, i) => (
            <TiltCard
              key={tool.id}
              className="ash-card"
              data-ash-reveal
              style={{
                "--ash-a": tool.hue[0],
                "--ash-b": tool.hue[1],
                "--ash-delay": `${(i % 3) * 70}ms`,
              }}
            >
              <div className="ash-card-glare" aria-hidden="true" />
              <div className="ash-card-glow" aria-hidden="true" />
              <div className="ash-card-top">
                <span className="ash-card-icon" aria-hidden="true">
                  {tool.icon}
                </span>
                <span className="ash-card-tag">{tool.tag}</span>
              </div>
              <h3 className="ash-card-name">{tool.name}</h3>
              {/* The exact tab label inside, so what you read here is findable
                  the moment you sign in. */}
              <p className="ash-card-where">
                Tab: <span>{tool.tab}</span>
              </p>
              <p className="ash-card-tagline">{tool.tagline}</p>
              <ul className="ash-card-bullets">
                {tool.bullets.map((b, bi) => (
                  <li key={bi}>{b}</li>
                ))}
              </ul>
              <button
                type="button"
                className="ash-card-try"
                data-cursor="Launch"
                onClick={() => handleTry(tool)}
              >
                <span className="ash-lock" aria-hidden="true">
                  🔒
                </span>
                Try it — sign in
              </button>
            </TiltCard>
          ))}
        </div>
      </section>

      {/* ================= UNDER THE HOOD ================= */}
      <section className="ash-stack">
        <div className="ash-section-head" data-ash-reveal>
          <span className="ash-kicker">03 — Under the hood</span>
          <h2>How it's engineered</h2>
          <p>
            The part recruiters usually ask about — the architecture behind the
            page you're on.
          </p>
        </div>

        <div className="ash-stack-grid">
          {STACK.map((item, i) => (
            <TiltCard
              key={item.title}
              className="ash-stack-card"
              data-ash-reveal
              style={{
                "--ash-a": item.hue[0],
                "--ash-b": item.hue[1],
                "--ash-delay": `${(i % 3) * 70}ms`,
              }}
            >
              <div className="ash-card-glare" aria-hidden="true" />
              <div className="ash-card-glow" aria-hidden="true" />
              <div className="ash-stack-top">
                <span className="ash-stack-icon" aria-hidden="true">
                  {item.icon}
                </span>
                <span className="ash-card-tag">{item.label}</span>
              </div>
              <h3>{item.title}</h3>
              <p>{item.desc}</p>
            </TiltCard>
          ))}
        </div>
      </section>

      {/* ================= BOTTOM CTA ================= */}
      <section className="ash-cta" data-ash-reveal>
        <div className="ash-cta-glow" aria-hidden="true" />
        <h2>See it for yourself</h2>
        <p>
          One Google sign-in unlocks all nine tools. Kick the tires — that's
          what they're here for.
        </p>
        {signinBlock}
      </section>
    </div>
  );
};

export default AgentsShowcase;
